"""Synthetic sample data — CLEARLY NOT REAL MARKET DATA.

The generator produces a plausible-looking daily OHLCV series with regime
switches (trending up, trending down, range-bound, high-volatility) so that
indicators, signals and the UI can be exercised without any paid API.

Nothing here should be used to judge a strategy's real-world performance.
"""
from __future__ import annotations

from datetime import datetime, timezone

import numpy as np
import pandas as pd

from .base import DataKind, DataProvenance, MarketDataset

SYNTHETIC_BANNER = (
    "SYNTHETIC DATA — generated by NIFTY Signal Lab for demonstration only. "
    "It is NOT real NIFTY history and must not be used to validate any strategy."
)

# (name, drift per day, daily vol, length in trading days)
_REGIMES = [
    ("bull", 0.0010, 0.0085, 160),
    ("range", 0.0000, 0.0070, 120),
    ("bear", -0.0010, 0.0130, 90),
    ("high_vol_range", 0.0001, 0.0180, 70),
    ("bull", 0.0011, 0.0090, 180),
    ("range", 0.0000, 0.0065, 130),
]


def generate_synthetic_nifty(
    start: str = "2023-01-02",
    start_price: float = 22_400.0,
    seed: int = 42,
    n_days: int | None = None,
) -> MarketDataset:
    """Generate a deterministic synthetic daily NIFTY-like series."""
    rng = np.random.default_rng(seed)
    drifts: list[float] = []
    vols: list[float] = []
    for _, mu, sigma, n in _REGIMES:
        drifts.extend([mu] * n)
        vols.extend([sigma] * n)
    total = len(drifts) if n_days is None else n_days
    drifts_arr = np.resize(np.array(drifts), total)
    vols_arr = np.resize(np.array(vols), total)

    log_returns = drifts_arr + vols_arr * rng.standard_normal(total)
    close = start_price * np.exp(np.cumsum(log_returns))

    # Build OHLC around close with intraday ranges proportional to vol.
    prev_close = np.concatenate([[start_price], close[:-1]])
    gap = prev_close * (rng.standard_normal(total) * vols_arr * 0.35)
    open_ = prev_close + gap
    intraday_range = close * vols_arr * rng.uniform(0.6, 1.6, total)
    hi_base = np.maximum(open_, close)
    lo_base = np.minimum(open_, close)
    high = hi_base + intraday_range * rng.uniform(0.2, 0.7, total)
    low = lo_base - intraday_range * rng.uniform(0.2, 0.7, total)
    low = np.maximum(low, 1.0)

    base_volume = 250_000_000
    volume = base_volume * (1 + 3 * vols_arr / 0.01 * 0.15) * rng.lognormal(0, 0.25, total)

    idx = pd.bdate_range(start=start, periods=total, freq="B")  # Mon-Fri; holidays ignored
    df = pd.DataFrame(
        {"open": open_, "high": high, "low": low, "close": close, "volume": volume.round()},
        index=idx,
    )
    df.index.name = "date"
    prov = DataProvenance(
        kind=DataKind.SYNTHETIC,
        source="nifty_lab.data.sample.generate_synthetic_nifty(seed=%d)" % seed,
        symbol="NIFTY (SYNTHETIC)",
        retrieved_at=datetime.now(timezone.utc),
        last_bar_time=idx[-1].to_pydatetime().replace(tzinfo=timezone.utc),
        notes=SYNTHETIC_BANNER,
    )
    return MarketDataset(df=df, provenance=prov)


def write_sample_csv(path: str, seed: int = 42) -> None:
    ds = generate_synthetic_nifty(seed=seed)
    out = ds.df.copy()
    out.insert(0, "date", out.index.strftime("%Y-%m-%d"))
    with open(path, "w", encoding="utf-8") as fh:
        fh.write("# " + SYNTHETIC_BANNER + "\n")
        out.to_csv(fh, index=False, float_format="%.2f")
